package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.List;

final class DiscoveryReconciliationBrowserAcceptance {
 static void click(Page p,String name){p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName(name).setExact(true)).press("Enter");}
 static void run(BrowserTest h)throws Exception {
  try(var e=new VulnerabilityResponseAcceptance.Endpoint(h.store,h.environment);var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()) {
   e.payload.set(JSON.writeValueAsString(DiscoveryReconciliationAcceptance.report(1,List.of(DiscoveryReconciliationAcceptance.entry("BROWSER-DISCOVERY","First observed value <script>")))));var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/discovery");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Configure another discovery source")).press("Enter");page.getByLabel("Source name").fill("Workplace hardware inventory <script>");page.getByLabel("Connector alias").fill(e.provider.alias);page.getByLabel("Observation report path").fill("/scan");page.getByLabel("Authority rank").fill("10");page.getByLabel("New configuration items").selectOption("true");page.getByLabel("Existing configuration items").selectOption("true");page.getByLabel("Source availability").selectOption("true");click(page,"Save discovery source");String sourceUrl=page.url();click(page,"Import current observation report");assertThat(page.locator("main")).containsText("Outcome: created");assertEquals("Bearer synthetic-question-token",e.provider.authorization.get());ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/discovery-report-light.png")).setFullPage(true));page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Discovered workstation <script>").setExact(true)).press("Enter");String ciUrl=page.url();assertThat(page.locator("main")).containsText("Canonical serial: BROWSER-DISCOVERY");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Configuration item workspace").setExact(true)).press("Enter");page.locator("textarea[name=description]").fill("Physically verified manual description");click(page,"Save changes →");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Discovery provenance").setExact(true)).press("Enter");assertThat(page.locator("main")).containsText("Manual change detected");
   e.payload.set(JSON.writeValueAsString(DiscoveryReconciliationAcceptance.report(2,List.of(DiscoveryReconciliationAcceptance.entry("BROWSER-DISCOVERY","New source observation")))));page.navigate(sourceUrl);click(page,"Import current observation report");assertThat(page.locator("main")).containsText("manual_conflict");page.navigate(ciUrl);page.getByLabel("Release reason for description").fill("Compared the manual and source evidence; allow the next observation");click(page,"Release description to discovery");assertThat(page.getByLabel("Release reason for description")).hasCount(0);
   e.payload.set(JSON.writeValueAsString(DiscoveryReconciliationAcceptance.report(3,List.of(DiscoveryReconciliationAcceptance.entry("BROWSER-DISCOVERY","Accepted fresh source value")))));page.navigate(sourceUrl);click(page,"Import current observation report");assertThat(page.locator("main")).containsText("Outcome: updated");page.navigate(ciUrl);assertThat(page.locator("main")).not().containsText("Manual change detected");click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertThat(page.locator("main script")).hasCount(0);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/discovery-provenance-dark.png")).setFullPage(true));page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Configuration item workspace").setExact(true)).press("Enter");assertThat(page.locator("textarea[name=description]")).hasValue("Accepted fresh source value");
   page.navigate(sourceUrl);page.getByLabel("New configuration items").selectOption("false");page.getByLabel("Existing configuration items").selectOption("false");page.getByLabel("Source availability").selectOption("false");click(page,"Save discovery source");assertThat(page.locator("main")).containsText("Activate the source with an available connector to import");assertThat(page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Import current observation report"))).hasCount(0);
  }
 }
}
